console.log("départ");
const resultat = Promise.resolve(12);
resultat
  .then(valeur => console.log(valeur * 2))
  .catch(erreur => console.log(erreur.message));
console.log("suite");

async function afficher() {
  try {
    const valeur = await Promise.resolve(12);
    console.log(valeur * 2);
  } catch (erreur) {
    console.log(erreur.message);
  }
}
afficher();
